import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(System.out);
        TaskC solver = new TaskC();
        solver.solve(1, br, pw);
        pw.close();
    }

    static class TaskC {
        final double EPS = 1e-8;

        public void solve(int testNumber, BufferedReader br, PrintWriter out) throws IOException {
            int n = Integer.parseInt(br.readLine());
            Circle[] circles = new Circle[n];
            for (int i = 0; i < n; i++) {
                String[] parts = br.readLine().split(" ");
                int x = Integer.parseInt(parts[0]);
                int y = Integer.parseInt(parts[1]);
                int r = Integer.parseInt(parts[2]);
                circles[i] = new Circle(new Point(x, y), r);
            }

            Set<Point> pointsSet = new TreeSet<>();
            for (int i = 0; i < n; i++) {
                for (int j = i + 1; j < n; j++) {
                    List<Point> inters = intersectCircles(circles[i], circles[j]);
                    if (inters != null) {
                        pointsSet.addAll(inters);
                    }
                }
            }

            Map<Point, Integer> pointIndices = new TreeMap<>();
            List<Set<Integer>> adjacency = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                List<Double> angles = new ArrayList<>();
                final int K = 100;
                for (int j = 0; j < K; j++) {
                    angles.add(2 * Math.PI * j / K);
                }
                for (Point p : pointsSet) {
                    if (circles[i].contains(p)) {
                        double dx = p.x - circles[i].o.x;
                        double dy = p.y - circles[i].o.y;
                        double angle = Math.atan2(dy, dx);
                        if (angle < 0) angle += 2 * Math.PI;
                        angles.add(angle);
                    }
                }
                Collections.sort(angles);
                Point direction = new Point(1,0).scale(circles[i].r);
                Double[] sortedAngles = new TreeSet<>(angles).toArray(new Double[0]);
                for (Double a : sortedAngles) {
                    Point p = circles[i].o.add(direction.rotate(a));
                    assignId(p, pointIndices, adjacency);
                }
                for (int j = 0; j < sortedAngles.length; j++) {
                    Point p1 = circles[i].o.add(direction.rotate(sortedAngles[j]));
                    Point p2 = circles[i].o.add(direction.rotate(sortedAngles[(j + 1) % sortedAngles.length]));
                    int u = pointIndices.get(p1);
                    int v = pointIndices.get(p2);
                    if (u != v) {
                        adjacency.get(u).add(v);
                        adjacency.get(v).add(u);
                    }
                }
            }

            int totalVertices = adjacency.size();
            int totalEdges = 0;
            for (Set<Integer> neighbors : adjacency) {
                totalEdges += neighbors.size();
            }
            totalEdges /= 2;

            int componentCount = 0;
            boolean[] visited = new boolean[totalVertices];
            for (int i = 0; i < totalVertices; i++) {
                if (!visited[i]) {
                    componentCount++;
                    dfs(i, visited, adjacency);
                }
            }

            out.println(1 + componentCount + totalEdges - totalVertices);
        }

        private void dfs(int node, boolean[] visited, List<Set<Integer>> adj) {
            visited[node] = true;
            for (int neighbor : adj.get(node)) {
                if (!visited[neighbor]) dfs(neighbor, visited, adj);
            }
        }

        private void assignId(Point p, Map<Point, Integer> pointId, List<Set<Integer>> adj) {
            if (!pointId.containsKey(p)) {
                int id = pointId.size();
                pointId.put(p, id);
                adj.add(new TreeSet<>());
            }
        }

        private List<Point> intersectCircles(Circle c1, Circle c2) {
            double dx = c1.o.x - c2.o.x;
            double dy = c1.o.y - c2.o.y;
            double d = Math.hypot(dx, dy);
            double cosA = (c1.r * c1.r + d * d - c2.r * c2.r) / (2 * c1.r * d);
            if (cosA < -1 - EPS || cosA > 1 + EPS) return null;
            if (cosA < -1) cosA = -1;
            if (cosA > 1) cosA = 1;
            double alpha = Math.acos(cosA);
            Point dir = c2.o.sub(c1.o).norm();
            List<Point> res = new ArrayList<>();
            res.add(c1.o.add(dir.scale(c1.r).rotate(+alpha)));
            res.add(c1.o.add(dir.scale(c1.r).rotate(-alpha)));
            return res;
        }

        class Point implements Comparable<Point> {
            double x, y;
            Point(double x, double y) { this.x = x; this.y = y; }

            Point add(Point o) { return new Point(x + o.x, y + o.y); }
            Point sub(Point o) { return new Point(x - o.x, y - o.y); }
            Point rotate(double a) {
                double c = Math.cos(a), s = Math.sin(a);
                return new Point(x * c - y * s, x * s + y * c);
            }
            Point norm() {
                double len = length();
                if (len < EPS) return new Point(0,0);
                return scale(1.0 / len);
            }
            Point scale(double f) { return new Point(x * f, y * f); }
            double length() { return Math.hypot(x, y); }

            public String toString() {
                return String.format("%.6f %.6f", x, y);
            }

            public boolean equals(Object o) {
                if (!(o instanceof Point)) return false;
                Point p = (Point) o;
                return Math.abs(x - p.x) < EPS && Math.abs(y - p.y) < EPS;
            }

            public int compareTo(Point o) {
                if (Math.abs(x - o.x) > EPS) return Double.compare(x, o.x);
                return Double.compare(y, o.y);
            }
        }

        class Circle {
            Point o;
            double r;
            Circle(Point o, double r) { this.o = o; this.r = r; }
            boolean contains(Point p) { return Math.abs(p.sub(o).length() - r) < EPS; }
        }
    }
